WITH hist AS (
 SELECT i.*,o.supplier_id,o.order_date,o.promised_date,
 LAG(i.unit_price_cents) OVER(PARTITION BY o.supplier_id,i.product_id ORDER BY o.order_date,i.po_item_id) AS prev_price
 FROM purchase_order_items i JOIN purchase_orders o ON i.po_id=o.po_id
 WHERE o.status<>'cancelled' AND o.order_date<'2026-01-01'
), compared AS (
 SELECT h.*,c.unit_price_cents AS contract_price
 FROM hist h LEFT JOIN supplier_contracts c ON h.contract_id=c.contract_id AND h.supplier_id=c.supplier_id AND h.product_id=c.product_id AND h.order_date>=c.start_date AND h.order_date<=c.end_date
 WHERE h.order_date>='2025-01-01'
) SELECT COUNT(*) AS due_lines,COUNT(contract_price) AS comparable_lines,SUM(CASE WHEN unit_price_cents<=contract_price THEN 1 ELSE 0 END) AS compliant_lines,100.0*SUM(CASE WHEN unit_price_cents<=contract_price THEN 1 ELSE 0 END)/NULLIF(COUNT(contract_price),0) AS compliance_pct FROM compared WHERE promised_date>='2025-01-01' AND promised_date<'2026-01-01';

