), compared AS (
 SELECT h.*,c.unit_price_cents AS contract_price
 FROM hist h LEFT JOIN supplier_contracts c ON h.contract_id=c.contract_id AND h.supplier_id=c.supplier_id AND h.product_id=c.product_id AND h.order_date>=c.start_date AND h.order_date<=c.end_date
 WHERE h.order_date>='2025-01-01'
) , supplier_prices AS (SELECT product_id,supplier_id,SUM(quantity_ordered*unit_price_cents)*1.0/NULLIF(SUM(quantity_ordered),0) AS weighted_price FROM compared GROUP BY product_id,supplier_id HAVING SUM(quantity_ordered)>0), benchmark AS (SELECT product_id,MIN(weighted_price) AS min_price FROM supplier_prices GROUP BY product_id HAVING COUNT(*)>=2) SELECT s.product_id,s.supplier_id,s.weighted_price,b.min_price,100.0*(s.weighted_price-b.min_price)/NULLIF(b.min_price,0) AS premium_pct FROM supplier_prices s JOIN benchmark b ON s.product_id=b.product_id ORDER BY s.product_id,s.supplier_id;

